<?php
/**
 * Tests that the readme discloses exactly the services the gateway declares and the two its PayPal form sends the shopper's browser to
 *
 * @package SEOCart\GatewayForPayPal
 * @since   0.2.0
 * @license GPL-3.0-or-later
 */

declare( strict_types=1 );

namespace SEOCart\GatewayForPayPal\Tests\Unit;

use SEOCart\GatewayForPayPal\Island;
use SEOCart\GatewayForPayPal\Tests\Support\GatewayTestCase;
use SEOCart\Tools\Docs\ExternalServicesSection;

/**
 * The "External services" section of readme.txt is generated by SEOCart's own generator from the hosts the gateway
 * declares, which the site calls, and from the two PayPal services the checkout's PayPal form sends the shopper's browser
 * to, PayPal's script and PayPal's approval page (Island::paypalScript(), Island::approvalPage()); this test fails when
 * the section and the declarations drift apart, and its message is the section to paste.
 *
 * Planted violations, each shown red and removed: a sentence of the section edited by hand; the PayPal script's entry
 * left out of the section: the test fails.
 *
 * @since 0.2.0
 */
final class ExternalServicesTest extends GatewayTestCase {

	/**
	 * Tests that the readme's section is the generator's output over the gateway's hosts and the PayPal form's two services.
	 *
	 * @since 0.2.0
	 */
	public function test_the_readme_discloses_the_declared_hosts(): void {
		$readme    = (string) file_get_contents( dirname( __DIR__, 2 ) . '/readme.txt' );
		$generator = new ExternalServicesSection( array( ...$this->gateway->describe()->hosts, Island::paypalScript(), Island::approvalPage() ) );

		$this->assertSame( $generator->generate( $readme )->content, $readme, "readme.txt's External services section must read:\n\n" . $generator->render() );
	}
}
